class Node(object):

    def __init__(self, data):
        self.data = data
        self.next = None


class Queue(object):

    def __init__(self):
        self.head = None
        self.tail = None

    def enqueue(self, data):
        node = Node(data)
        # Empty list
        if self.head is None and self.tail is None:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            self.tail = node

    def dequeue(self):
        # Empty list
        if self.head is None and self.tail is None:
            return None
        data = self.head.data
        # Remove only element from a one element list
        if self.head == self.tail:
            self.head = None
            self.tail = None
        else:
            self.head = self.head.next
        return data


def run(ops):
    """Given: plays the tests' operations on a Queue and returns what each dequeue gives."""
    queue, out = Queue(), []
    for op, *args in ops:
        if op == 'enqueue':
            queue.enqueue(*args)
        else:
            out.append(queue.dequeue())
    return out

